mapper.select:
SELECT FROM TBL_KPI_INDICATOR WHERE INDICATOR_CATEGORY = #{indicatorCategory} AND DEL_FLAG = '0'
AND ORG_ID = #{orgId}
ORDER BY INDICATOR_NAME ASC

SELECT FROM TBL_KPI_INDICATOR WHERE INDICATOR_STATUS = #{indicatorStatus} AND DEL_FLAG = '0'
AND ORG_ID = #{orgId}
ORDER BY TARGET_VALUE DESC

SELECT FROM TBL_KPI_INDICATOR WHERE DEL_FLAG = '0' AND ( CURRENT_VALUE >= REMIND_THRESHOLD OR (TARGET_VALUE - CURRENT_VALUE) / TARGET_VALUE * 100 >= REMIND_THRESHOLD )
AND ORG_ID = #{orgId}
ORDER BY CURRENT_VALUE DESC

SELECT INDICATOR_TYPE, INDICATOR_CATEGORY, COUNT(*) as indicatorCount, AVG(CURRENT_VALUE) as avgCurrentValue, AVG(TARGET_VALUE) as avgTargetValue, SUM(CASE WHEN CURRENT_VALUE >= TARGET_VALUE THEN 1 ELSE 0 END) as targetAchievedCount FROM TBL_KPI_INDICATOR WHERE DEL_FLAG = '0'
AND ORG_ID = #{orgId}
GROUP BY INDICATOR_TYPE, INDICATOR_CATEGORY ORDER BY INDICATOR_TYPE, INDICATOR_CATEGORY

SELECT INDICATOR_CODE, INDICATOR_NAME, CURRENT_VALUE, TARGET_VALUE, CREATE_TIME FROM TBL_KPI_INDICATOR WHERE DEL_FLAG = '0' AND INDICATOR_CODE IN
#{item}
AND ORG_ID = #{orgId}
ORDER BY INDICATOR_CODE, CREATE_TIME DESC

SELECT

FROM TBL_KPI_INDICATOR
WHERE DEL_FLAG = '0'

    AND KPI_CODE LIKE '%' || #{kpiCode} || '%'


    AND KPI_NAME LIKE '%' || #{kpiName} || '%'


    AND KPI_CATEGORY = #{kpiCategory}


    AND KPI_TYPE = #{kpiType}


    AND KPI_STATUS = #{kpiStatus}


    AND ORG_ID = #{orgId}

ORDER BY CREATE_TIME DESC
